#include <cstdint>
#include <cstring>
#include <exception>
#include <stdexcept>
#include <ImfIO.h>
#include <ImfInputFile.h>
#include <ImfNamespace.h>

class MemoryIStream : public OPENEXR_IMF_NAMESPACE::IStream {
 public:
  MemoryIStream(const char* data, int64_t size)
      : OPENEXR_IMF_NAMESPACE::IStream("<memory>"), _data(data), _size(size), _pos(0) {}

  bool read(char c[], int n) override {
    if (_pos + n > _size) {
      throw std::runtime_error("read past end");
    }
    std::memcpy(c, _data + _pos, static_cast<size_t>(n));
    _pos += n;
    return _pos < _size;
  }

  uint64_t tellg() override { return static_cast<uint64_t>(_pos); }
  void seekg(uint64_t pos) override { _pos = static_cast<int64_t>(pos); }

 private:
  const char* _data;
  int64_t _size;
  int64_t _pos;
};

extern "C" int LLVMFuzzerTestOneInput(const uint8_t* data, size_t size) {
  MemoryIStream stream(reinterpret_cast<const char*>(data), static_cast<int64_t>(size));
  try {
    OPENEXR_IMF_NAMESPACE::InputFile file(stream);
    const OPENEXR_IMF_NAMESPACE::Header& header = file.header();
    const IMATH_NAMESPACE::Box2i& dataWindow = header.dataWindow();
    static_cast<void>(dataWindow.max.x - dataWindow.min.x);

  } catch (const std::exception&) {
  }
  return 0;
}

